    'an_agent_is_any_software_that_acts_on_this_e_05aebde2' => 'Agentti on mikä tahansa ohjelmisto, joka toimii tässä ympäristössä hallintaavaimella: AI-avustaja, kuten Claude Code tai Cursor, sisäinen botti tai oma taustajärjestelmäsi. Anna kullekin oma avain vain sen tarvitsemilla laajuuksilla, päätä, mitkä sen toiminnoista odottavat hyväksyntääsi, ja peruuta avain heti, kun agentti on valmis tai jokin näyttää vialta.',
