    'each_pipe_lets_people_connect_their_own_acco_ec4853ae' => 'Jokaisen putken avulla ihmiset voivat yhdistää oman tilinsä palvelussa, kuten GitHub, Google tai Slack. Heidän tunnuksensa tallennetaan salattuna ja pidetään tuoreena täällä; myöntämäsi sovellukset pyytävät toimivaa tunnusta aina, kun he soittavat kyseiseen palveluun henkilönä, eivätkä koskaan tallenna sitä itse.',
    'each_project_in_your_workspace_has_its_own_p_c5ff35b1' => 'Jokaisella työtilasi projektilla on oma suunnitelmansa ja ympäristörajoituksensa, jotka näkyvät tässä tämän kuun käytön vieressä: organisaatiot, laskutetut kertakirjautumisyhteydet ja kirjautumiset. Hinnoitteluun lasketaan kuukausittaiset aktiiviset käyttäjät ja yritysyhteydet, kuten kertakirjautuminen ja SCIM, ja hiekkalaatikkoympäristöistä ei peritä yhteysmaksua.',
