    'every_action_is_accepted_as_your_app_sends_i_fce48faa' => 'Jokainen toiminto hyväksytään, kun sovellus lähettää sen. Lisää toiminnolle skeema, jotta sen tapahtumat tarkistetaan saapuessa – johdonmukainen loki päätetään, kun tapahtuma kirjoitetaan, ei silloin, kun joku lukee sitä.',
    'every_administrative_change_members_roles_co_ef641619' => 'Jokainen hallinnollinen muutos – jäsenet, roolit, yhteydet, sovellukset – saapuu tänne sellaisena kuin se tapahtuu, kuka sen teki ja milloin. Ei mitään määritettävää; se tallentaa itsensä.',
    'every_api_key_sitting_in_an_app_s_config_or__975161a8' => 'Jokaista sovelluksen asetus- tai ympäristötiedostossa olevaa API-avainta ei voi kiertää keskitetysti tai ottaa pois kiireessä. Täällä tallennettu se on salattu, myönnetty sovelluskohtaisesti ja peruutettavissa yhdellä napsautuksella.',
    'every_api_key_the_people_in_this_organizatio_15e73625' => 'Jokainen API-avain, jonka tämän organisaation ihmiset ovat luoneet sen sovelluksille. Peruuta sellainen, joka on vuotanut tai jota ei enää käytetä. Ihmiset luovat omat avaimensa Oma tili -kohdassa.',
    'every_api_key_the_people_in_this_organizatio_fe7787a7' => 'Jokainen API-avain, jonka tämän organisaation ihmiset ovat luoneet sen sovelluksille: kenen hallussa se on, mihin sovellukseen se on tarkoitettu, mitä se voi tehdä ja milloin sitä on käytetty viimeksi. Avain voi tehdä vain sen, mitä sen haltija pystyy, ja lakkaa toimimasta, kun ne lähtevät. Peruuta sellainen, joka on vuotanut tai jota ei enää käytetä; jokainen luo omat avaimensa Oma tili -kohtaan.',
    'every_app_asking_for_this_flag_gets_off_this_e3ed99c1' => 'Jokainen sovellus, joka pyytää tätä lippua, sammuu. Tätä ei voi kumota.',
    'every_app_that_signs_people_in_through_cbox__1e151c65' => 'Jokainen sovellus, joka kirjaa ihmisiä sisään Cbox ID:n kautta tai soittaa sen API, rekisteröidään täällä ja saa omat kirjautumistietonsa. Rekisteröi yksi sovellusta ja ympäristöä kohti – älä koskaan jaa tunnistetietoja niiden välillä, joten voit peruuttaa yhden ilman, että poistat muita.',
    'every_app_that_signs_people_in_through_cbox__bf1c3a89' => 'Jokainen sovellus, joka kirjaa ihmisiä sisään Cbox ID:n kautta tai kutsuu sitä API, on rekisteröity täällä.',
    'every_audit_log_entry_mirrored_into_your_sie_a5cc2e26' => 'Jokainen tarkastuslokin merkintä peilattu SIEM:ään tai ämpäriin sellaisena kuin se on kirjoitettu – Splunk, Datadog, Elastic, S3.',
