    'every_browser_and_device_signed_in_as_you_th_ee516093' => 'Jokainen käyttäjänä kirjautuneena selain ja laite, sovellukset, jotka olet antanut toimia puolestasi, sekä viimeaikaiset kirjautumisesi ja tietoturvamuutoksesi. Jos jokin tässä ei ole sinun, kirjaudu ulos tai poista sovellus ja vaihda salasanasi.',
