    'let_an_organization_sign_in_with_okta_entra__cf114dfb' => 'Anna organisaation kirjautua sisään Oktalla, Entra ID:llä tai Google Workspacella – tai lähetä järjestelmänvalvojalle Admin Portal -linkki, jotta se voi tehdä sen itse.',
    'let_people_sign_in_with_an_account_they_alre_de3c77a6' => 'Anna ihmisten kirjautua sisään tilillä, joka heillä jo on. Määritä ympäristölle kerran palveluntarjoaja, ja jokainen organisaatio tarjoaa sen; organisaatio voi tuoda sen sijaan omat tunnistetietonsa tai poistaa ne käytöstä.',
