    'let_the_people_who_use_your_apps_connect_the_19a2d0ed' => 'Anna sovelluksiasi käyttävien ihmisten yhdistää omat GitHub-, Google-, Slack- tai Salesforce-tilinsä, jotta sovelluksesi voivat soittaa kyseisille sovellusliittymille heidän puolestaan. Heidän tunnuksensa tallennetaan salattuna, päivitetään täällä ja vuokrataan vain myöntämillesi sovelluksille.',
    'let_your_apps_declare_the_roles_they_underst_719f1d4a' => 'Anna sovellusten ilmoittaa roolit, joita he ymmärtävät – ne saapuvat tänne itsekseen.',
    'let_your_identity_provider_create_update_and_1208087e' => 'Anna identiteetintarjoajan luoda, päivittää ja deaktivoida ihmisiä täällä yksin – ja yhdistää sen ryhmät rooleihisi.',
    'let_your_provider_create_and_deactivate_peop_7db65233' => 'Anna palveluntarjoajan luoda ja deaktivoida ihmisiä täällä itse, jotta poistuva menettää pääsyn kaikkialle ilman lippua.',
    'lets_the_people_who_use_this_app_create_api__ba2ebdce' => 'Antaa tätä sovellusta käyttävien ihmisten luoda API-avaimia sen API kohtaan Oma tili › API-avaimet – kukin niihin sidottu, yksi organisaatio ja osa heidän käyttöoikeuksistaan ​​tässä sovelluksessa. API tarkistaa avaimen soittamalla numeroon Cbox ID tämän sovelluksen omilla kirjautumistiedoilla, ja avain menettää käyttöoikeuden heti, kun sen haltija tekee.',
    'lets_this_app_trade_a_token_it_was_given_for_e3add8e6' => 'Antaa tämän sovelluksen vaihtaa sen saaman tunnuksen toiselle palvelullesi, kapeammalle tai eri yleisölle tarkoitetulla tunnuksella, tavallisen tunnuksenvaihtoavustuksen (RFC 8693) sijaan. Ota se käyttöön taustajärjestelmässä, joka soittaa lisäpalveluihin henkilön puolesta.',
    'lets_your_people_sign_in_with_the_company_ac_5186cda3' => 'Sallii ihmisten kirjautua sisään heillä jo olevilla yritystilillä – Microsoft Entra ID, Okta, Google Workspace – erillisen salasanan sijaan. Yhdistät identiteetintarjoajaasi kerran ja lunastat sähköpostiverkkotunnuksesi. kaikki näiden verkkotunnusten käyttäjät lähetetään sitten palveluntarjoajallesi kirjautumaan sisään.',
    'letting_your_people_sign_in_with_entra_id_ok_10c80076' => 'Enterprise-paketissa on mahdollisuus kirjautua sisään Entra ID:llä, Oktalla tai Google Workspacella. Ota yhteyttä tilitiimiisi ottaaksesi sen käyttöön tässä organisaatiossa.',
